const binary = await this.helpers.getBinaryDataBuffer(0, 'data');
const csv = binary.toString('utf8');
const lines = csv.replace(/^\uFEFF/, '').split(/\r?\n/).filter(Boolean);
if (lines.length < 2) return [];
const split = (line) => { const cells = []; let cell = ''; let quoted = false; for (let i = 0; i < line.length; i++) { const c = line[i]; if (quoted && c === '"' && line[i + 1] === '"') { cell += '"'; i++; } else if (c === '"') quoted = !quoted; else if (!quoted && c === ',') { cells.push(cell.trim()); cell = ''; } else cell += c; } cells.push(cell.trim()); return cells; };
const headers = split(lines[0]).map(h => h.toLowerCase().replace(/[\s_/-]+/g, ''));
const bank = headers.includes('dk') ? 'bca' : headers.includes('jenis') ? 'mandiri' : (() => { throw new Error('Bank CSV tidak dikenali'); })();
const at = (name) => { const index = headers.indexOf(name); if (index < 0) throw new Error(`Kolom ${name} tidak ditemukan`); return index; };
const dateIndex = at('tanggal'); const merchantIndex = at('keterangan'); const amountIndex = at('jumlah'); const typeIndex = at(bank === 'bca' ? 'dk' : 'jenis');
const parseDate = (value) => { const parts = value.split(/[\/-]/).map(Number); const date = parts[0] > 31 ? new Date(Date.UTC(parts[0], parts[1] - 1, parts[2])) : new Date(Date.UTC(parts[2], parts[1] - 1, parts[0])); if (Number.isNaN(date.getTime())) throw new Error(`Tanggal tidak valid: ${value}`); return date.toISOString(); };
const parseAmount = (value) => { const digits = value.replace(/[^0-9,.-]/g, ''); const amount = digits.includes('.') && digits.includes(',') ? Number(digits.replace(/\./g, '').replace(',', '.')) : Number(digits.replace(/[.,]/g, '')); if (!Number.isSafeInteger(amount)) throw new Error(`Jumlah tidak valid: ${value}`); return Math.abs(amount); };
const items = lines.slice(1).map((line, index) => { const row = split(line); const kind = row[typeIndex].toLowerCase(); const type = ['k', 'kredit', 'credit', 'cr', 'c'].includes(kind) ? 'income' : 'expense'; return { source_ref: `${bank}:${index + 1}`, parsed: { occurred_at: parseDate(row[dateIndex]), merchant: row[merchantIndex], amount: parseAmount(row[amountIndex]), type } }; }); const batches = []; for (let i = 0; i < items.length; i += 200) batches.push({ json: { source: `bank_csv_${bank}`, source_ref_prefix: `${bank}:`, items: items.slice(i, i + 200) } }); return batches;
